ext:createCollection.ext:options:
{
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["_id", "order_id", "user_id", "status", "timestamp", "payment_amount"],
      properties: {
        _id:            { bsonType: "string",  description: "payment id (UUID)" },
        order_id:       { bsonType: "string" },
        user_id:        { bsonType: "string" },
        status:         { enum: ["PENDING", "COMPLETED", "FAILED", "REFUNDED", "CANCELLED"] },
        timestamp:      { bsonType: "date" },
        payment_amount: { bsonType: "decimal", minimum: 0 }
      }
    }
  },
  validationLevel: "strict",
  validationAction: "error"
}
